        <div className="tracker-modal-grid"><label>Interview date<input required type="date" value={interviewTarget.interviewDate} onChange={event => setInterviewTarget({ ...interviewTarget, interviewDate: event.target.value })} /></label><label>Interview time<input required type="time" step="1" value={interviewTarget.interviewTime} onChange={event => setInterviewTarget({ ...interviewTarget, interviewTime: event.target.value })} /></label><label className="wide-field">Venue or online meeting link<input required value={interviewTarget.interviewVenue} onChange={event => setInterviewTarget({ ...interviewTarget, interviewVenue: event.target.value })} placeholder="Branch address or meeting link" /></label></div>
